const root = document.documentElement;
const langButtons = document.querySelectorAll("[data-lang]");
const navToggle = document.querySelector(".nav-toggle");
const nav = document.querySelector(".primary-nav");
const scenarioTabs = document.querySelectorAll(".scenario-tab");
const problemCarousel = document.querySelector(".problem-carousel");
const problemDots = Array.from(document.querySelectorAll("[data-problem-index]"));
let problemIndex = 0;

function renderProblem() {
  const lang = translations[root.lang] ? root.lang : "en";
  const slides = translations[lang].problemSlides;
  const [title, description, point] = slides[problemIndex];
  problemCarousel.querySelector(".problem-count").textContent = `${String(problemIndex + 1).padStart(2, "0")} / ${String(slides.length).padStart(2, "0")}`;
  problemCarousel.querySelector(".problem-story-title").textContent = title;
  problemCarousel.querySelector(".problem-story-text").textContent = description;
  problemCarousel.querySelector(".problem-story-point").textContent = point;
  problemDots.forEach((dot, index) => {
    dot.setAttribute("aria-current", String(index === problemIndex));
    dot.setAttribute("aria-label", `${translations[lang].problemChoose} ${index + 1}: ${slides[index][0]}`);
  });
}

function showProblem(index) {
  const count = translations[root.lang].problemSlides.length;
  problemIndex = (index + count) % count;
  renderProblem();
}

problemCarousel.querySelector("[data-problem-prev]").addEventListener("click", () => showProblem(problemIndex - 1));
problemCarousel.querySelector("[data-problem-next]").addEventListener("click", () => showProblem(problemIndex + 1));
problemDots.forEach((dot, index) => dot.addEventListener("click", () => showProblem(index)));
problemCarousel.addEventListener("keydown", (event) => {
  if (event.key === "Home") showProblem(0);
  else if (event.key === "End") showProblem(problemDots.length - 1);
  else if (event.key === "ArrowLeft") showProblem(problemIndex + (root.dir === "rtl" ? 1 : -1));
  else if (event.key === "ArrowRight") showProblem(problemIndex + (root.dir === "rtl" ? -1 : 1));
  else return;
  event.preventDefault();
});

scenarioTabs.forEach((tab) => tab.addEventListener("click", () => {
  scenarioTabs.forEach((item) => {
    const active = item === tab;
    item.classList.toggle("active", active);
    item.setAttribute("aria-selected", String(active));
    const panel = document.getElementById(item.getAttribute("aria-controls"));
    panel.classList.toggle("active", active);
    panel.hidden = !active;
  });
}));

function setLanguage(lang) {
  const selected = translations[lang] ? lang : "en";
  root.lang = selected;
  root.dir = selected === "ar" ? "rtl" : "ltr";
  document.querySelectorAll("[data-app-link]").forEach((link) => {
    const destination = new URL(link.href);
    destination.searchParams.set("lang", selected);
    destination.searchParams.set("theme", root.dataset.theme === "dark" ? "dark" : "light");
    link.href = destination.href;
  });
  document.querySelectorAll("[data-i18n]").forEach((element) => {
    const value = translations[selected][element.dataset.i18n];
    if (value) element.innerHTML = value;
  });
  document.querySelectorAll("[data-i18n-aria]").forEach((element) => {
    const value = translations[selected][element.dataset.i18nAria];
    if (value) element.setAttribute("aria-label", value);
  });
  renderProblem();
  langButtons.forEach((button) => {
    const active = button.dataset.lang === selected;
    button.classList.toggle("active", active);
    button.setAttribute("aria-pressed", String(active));
  });
  localStorage.setItem("relayqo-language", selected);
  document.title = selected === "fr" ? "Relayqo — Des conversations qui font avancer" : selected === "ar" ? "Relayqo — محادثات تدفع أعمالك إلى الأمام" : "Relayqo — Business conversations that move";
}

langButtons.forEach((button) => button.addEventListener("click", () => setLanguage(button.dataset.lang)));

navToggle.addEventListener("click", () => {
  const open = nav.classList.toggle("open");
  navToggle.setAttribute("aria-expanded", String(open));
});

nav.querySelectorAll("a").forEach((link) => link.addEventListener("click", () => {
  nav.classList.remove("open");
  navToggle.setAttribute("aria-expanded", "false");
}));

const observer = new IntersectionObserver((entries) => {
  entries.forEach((entry) => {
    if (entry.isIntersecting) {
      entry.target.classList.add("visible");
      observer.unobserve(entry.target);
    }
  });
}, { threshold: 0.12 });

document.querySelectorAll(".reveal").forEach((element) => observer.observe(element));
document.getElementById("year").textContent = new Date().getFullYear();
setLanguage(localStorage.getItem("relayqo-language") || "ar");
